#include <bits/stdc++.h>
using namespace std;
int main() {
    // 本例保留默认同步；因此cout/printf输出顺序可一起演示。
    double x = 12.3456;
    cout << setprecision(3) << x << '\n';
    cout << fixed << setprecision(3) << x << '\n';
    printf("%.10f\n", 0.125);
    printf("%.3Lf\n", 1.0L / 8);
    long double y = -1.5L;
    cout << setprecision(0) << floor(y) << ' ' << ceil(y) << ' '
         << round(y) << ' ' << trunc(y) << '\n';
}
